// 提取内容数据
const results = $json.results || [];

if (results.length === 0) {
  throw new Error('没有待发布的小红书内容（状态需为

）');
}

const page = results[0];
const props = page.properties;

const content = {
  notionPageId: page.id,
  contentId: props['内容ID']?.rich_text?.[0]?.text?.content || '',
  title: props['标题']?.title?.[0]?.text?.content || '',
  content: props['完整正文']?.rich_text?.[0]?.text?.content || '',
  tags: props['话题标签']?.multi_select?.map(t => t.name) || [],
  imagesJson: props['配图建议']?.rich_text?.[0]?.text?.content || '[]'
};

// 解析图片
try {
  content.images = JSON.parse(content.imagesJson);
} catch (e) {
  content.images = [];
}

return [{ json: content }];

// 格式化小红书发布内容
const d = $json;

// 小红书正文格式化
let formattedContent = d.content;

// 添加话题标签（小红书格式）
const tagsText = d.tags.map(t => `#${t}`).join(' ');
formattedContent += `\n\n${tagsText}`;

// 生成发布说明
const publishGuide = `【小红书发布指南】

1. 复制以下标题和正文
2. 登录小红书APP或网页版
3. 点击

发布后请记录：
- 笔记链接
- 笔记ID
- 发布时间`;

return [{
  json: {
    ...d,
    formattedContent,
    publishGuide,
    imageUrls: d.images.map(img => img.url).filter(url => url),
    imageCount: d.images.length
  }
}];

// 生成发布提示
const d = $json;

const message = `===========================================
小红书内容已准备就绪！
===========================================

【标题】
${d.title}

【正文】
${d.formattedContent}

【配图】
共${d.imageCount}张图片
${d.imageUrls.map((url, i) => `图${i+1}: ${url}`).join('\n')}

${d.publishGuide}

===========================================`;

console.log(message);

return [{
  json: {
    ...d,
    publishMessage: message,
    status: '待人工发布'
  }
}];

