const d = $json;

const body = {
  properties: {
    '状态': { select: { name: '待发布' } },
    '发布准备时间': { date: { start: new Date().toISOString() } }
  }
};

return [{
  json: {
    ...d,
    notionUpdateBody: JSON.stringify(body)
  }
}];

// 生成执行摘要
const d = $('构建Notion更新').item.json;

const summary = `小红书发布准备报告
===================
执行时间: ${new Date().toLocaleString('zh-CN')}

【内容信息】
- 内容ID: ${d.contentId}
- 标题: ${d.title}
- 字数: ${d.content.length}字
- 配图: ${d.imageCount}张
- 话题标签: ${d.tags.join('、')}

【发布内容】
${d.publishMessage}

【下一步】
1. 按照发布指南手动发布到小红书
2. 发布后记录笔记链接和ID
3. 在Notion中更新发布状态为

4. 填写发布链接和笔记ID

【提示】
- 建议发布时间：工作日19:00-21:00，周末10:00-12:00
- 发布后及时回复评论，提高互动率
- 监测数据表现，优化后续内容`;

return [{
  json: {
    report: summary,
    contentId: d.contentId,
    title: d.title,
    status: d.status,
    timestamp: new Date().toISOString()
  }
}];
